<?php
require_once __DIR__.'/includes/auth.php';require_login();require_once __DIR__.'/includes/olympia_store.php';olympia_ensure_schema();
$user=current_user()??[];$uid=olympia_user_id();$name=trim((string)($user['teacher_name']??$user['name']??$user['username']??''));$weeks=olympia_weeks();
if(empty($_SESSION['olympia_sets_csrf']))$_SESSION['olympia_sets_csrf']=bin2hex(random_bytes(24));$csrf=$_SESSION['olympia_sets_csrf'];
$weekId=trim((string)($_REQUEST['week']??($weeks[0]['id']??'')));$setId=trim((string)($_REQUEST['set']??''));$week=olympia_week($weekId);
function os_go(string $week,string $set=''):void{header('Location: '.BASE_URL.'hoclieu_game_olympia_sets.php?week='.rawurlencode($week).($set!==''?'&set='.rawurlencode($set):''));exit;}
function os_own(string $setId,string $weekId):array{$s=olympia_set($setId);if(!$s||(string)$s['week_id']!==$weekId||(!olympia_admin()&&(string)$s['owner_id']!==olympia_user_id()))throw new RuntimeException('Bộ câu hỏi không thuộc tài khoản này.');return $s;}
if($_SERVER['REQUEST_METHOD']==='POST'){try{if(!hash_equals($csrf,(string)($_POST['csrf']??'')))throw new RuntimeException('Phiên làm việc không hợp lệ.');$a=(string)($_POST['action']??'');$db=olympia_db();
 if($a==='create_set'){if(!$week)throw new RuntimeException('Không tìm thấy tuần.');$q=$db->prepare('SELECT COUNT(*) FROM cds_olympia_question_sets WHERE week_id=? AND owner_id=? AND is_archived=0');$q->execute([$weekId,$uid]);if((int)$q->fetchColumn()>=5)throw new RuntimeException('Mỗi tài khoản tối đa 5 bộ đang hoạt động trong một tuần. Hãy lưu trữ bộ cũ trước.');$title=trim((string)($_POST['title']??''));if($title==='')$title='Bộ câu hỏi của '.$name;$id=olympia_uid('os');$db->beginTransaction();$db->prepare("INSERT INTO cds_olympia_question_sets(id,week_id,owner_id,owner_name,title,status) VALUES(?,?,?,?,?,'draft')")->execute([$id,$weekId,$uid,$name,$title]);if(!empty($_POST['copy_official'])){$src=$db->prepare("SELECT grade_scope,stage_name,question_text,answer_text,points,sort_order FROM cds_olympia_questions WHERE week_id=? AND set_id='' ORDER BY sort_order,id");$src->execute([$weekId]);$ins=$db->prepare('INSERT INTO cds_olympia_questions(id,week_id,set_id,grade_scope,stage_name,question_text,answer_text,points,sort_order) VALUES(?,?,?,?,?,?,?,?,?)');foreach($src as $r)$ins->execute([olympia_uid('oq'),$weekId,$id,$r['grade_scope'],$r['stage_name'],$r['question_text'],$r['answer_text'],$r['points'],$r['sort_order']]);}$db->commit();os_go($weekId,$id);}
 if($a==='save_set'){os_own($setId,$weekId);$title=trim((string)($_POST['title']??''));if($title==='')throw new RuntimeException('Tên bộ không được để trống.');$status=in_array($_POST['status']??'',['draft','ready'],true)?$_POST['status']:'draft';$db->prepare('UPDATE cds_olympia_question_sets SET title=?,status=? WHERE id=?')->execute([$title,$status,$setId]);os_go($weekId,$setId);}
 if($a==='archive_set'){os_own($setId,$weekId);$db->prepare('UPDATE cds_olympia_question_sets SET is_archived=1 WHERE id=?')->execute([$setId]);os_go($weekId);}
 if($a==='delete_set'){os_own($setId,$weekId);$db->beginTransaction();$db->prepare('DELETE FROM cds_olympia_scores WHERE set_id=?')->execute([$setId]);$db->prepare('DELETE FROM cds_olympia_questions WHERE set_id=?')->execute([$setId]);$db->prepare('DELETE FROM cds_olympia_personal_live_sessions WHERE set_id=?')->execute([$setId]);$db->prepare('DELETE FROM cds_olympia_question_sets WHERE id=?')->execute([$setId]);$db->commit();os_go($weekId);}
 if($a==='update_question'){os_own($setId,$weekId);$qid=trim((string)($_POST['question_id']??''));$text=trim((string)($_POST['question_text']??''));if($text==='')throw new RuntimeException('Nội dung câu hỏi không được để trống.');$check=$db->prepare('SELECT id FROM cds_olympia_questions WHERE id=? AND week_id=? AND set_id=?');$check->execute([$qid,$weekId,$setId]);if(!$check->fetchColumn())throw new RuntimeException('Câu hỏi không thuộc bộ đang sửa.');$scope=!empty($_POST['all_grades'])?'all':olympia_normalize_grade_scope($_POST['grade_scopes']??[]);$db->prepare('UPDATE cds_olympia_questions SET grade_scope=?,stage_name=?,question_text=?,answer_text=?,points=?,sort_order=? WHERE id=? AND week_id=? AND set_id=?')->execute([$scope,trim((string)($_POST['stage_name']??'Khởi động')),$text,trim((string)($_POST['answer_text']??'')),max(0,(int)($_POST['points']??10)),max(0,(int)($_POST['sort_order']??0)),$qid,$weekId,$setId]);os_go($weekId,$setId);}
 if($a==='save_question'){os_own($setId,$weekId);$qid=trim((string)($_POST['question_id']??''))?:olympia_uid('oq');$text=trim((string)($_POST['question_text']??''));if($text==='')throw new RuntimeException('Thiếu nội dung câu hỏi.');$scope=!empty($_POST['all_grades'])?'all':olympia_normalize_grade_scope($_POST['grade_scopes']??[]);$stage=in_array($_POST['stage_name']??'', ['Khởi động','Vượt chướng ngại vật','Tăng tốc','Về đích'],true)?$_POST['stage_name']:'Khởi động';$check=$db->prepare('SELECT COUNT(*) FROM cds_olympia_questions WHERE id=? AND set_id=?');$check->execute([$qid,$setId]);if($check->fetchColumn())$db->prepare('UPDATE cds_olympia_questions SET grade_scope=?,stage_name=?,question_text=?,answer_text=?,points=?,sort_order=? WHERE id=? AND set_id=?')->execute([$scope,$stage,$text,trim((string)($_POST['answer_text']??'')),max(0,(int)($_POST['points']??10)),max(0,(int)($_POST['sort_order']??0)),$qid,$setId]);else $db->prepare('INSERT INTO cds_olympia_questions(id,week_id,set_id,grade_scope,stage_name,question_text,answer_text,points,sort_order) VALUES(?,?,?,?,?,?,?,?,?)')->execute([$qid,$weekId,$setId,$scope,$stage,$text,trim((string)($_POST['answer_text']??'')),max(0,(int)($_POST['points']??10)),max(0,(int)($_POST['sort_order']??0))]);os_go($weekId,$setId);}
 if($a==='delete_question'){os_own($setId,$weekId);$db->prepare('DELETE FROM cds_olympia_questions WHERE id=? AND set_id=?')->execute([$_POST['question_id']??'',$setId]);os_go($weekId,$setId);}
}catch(Throwable $e){if(isset($db)&&$db->inTransaction())$db->rollBack();$error=$e->getMessage();}}
$sets=$week?olympia_personal_sets($weekId):[];$set=$setId!==''?olympia_set($setId):null;if($set&&(!olympia_admin()&&(string)$set['owner_id']!==$uid))$set=null;$questions=$set?olympia_questions($weekId,'',$setId):[];
?><!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Bộ câu hỏi cá nhân Olympia</title><style>*{box-sizing:border-box}body{margin:0;background:#eef4f9;color:#18324a;font-family:Segoe UI,system-ui,sans-serif}.top{background:#083e70;color:#fff;padding:18px}.wrap{max-width:1200px;margin:auto}.card{background:#fff;border-radius:16px;padding:18px;margin:14px 0;box-shadow:0 4px 18px #1232}.row{display:flex;gap:10px;flex-wrap:wrap}.btn,input,select,textarea{border:1px solid #bfd0df;border-radius:9px;padding:10px;font:inherit}.btn{background:#126cad;color:#fff;text-decoration:none;font-weight:700;cursor:pointer}.safe{background:#e9f7ef;border-left:5px solid #2d9d62;padding:12px}.warn{background:#fff3cd;padding:10px;border-radius:8px}.set{display:flex;justify-content:space-between;gap:10px;padding:12px;border-bottom:1px solid #e5edf3}.q{padding:12px;border:1px solid #dce7ef;border-radius:10px;margin:8px 0}.muted{color:#6a7c8d;font-size:13px}textarea{width:100%;min-height:75px}@media(max-width:700px){.set{flex-direction:column}.row>*{width:100%}}</style></head><body><header class="top"><div class="wrap"><h1 style="margin:0">Bộ câu hỏi cá nhân Olympia</h1><div>Kho riêng của giáo viên · không cộng vào điểm/xếp hạng chính thức</div></div></header><main class="wrap"><?php if(!empty($error)):?><div class="card warn"><?=e($error)?></div><?php endif?><div class="card safe"><strong>An toàn dữ liệu:</strong> Bộ chính dùng mã hệ thống riêng; các bộ tại đây luôn có <code>set_id</code>. Điểm chơi thử chỉ ghi vào đúng bộ cá nhân và không được truy vấn trong bảng xếp hạng chính.</div><div class="card"><form class="row" method="get"><select name="week" onchange="this.form.submit()"><?php foreach($weeks as $w):?><option value="<?=e($w['id'])?>" <?=$weekId===$w['id']?'selected':''?>><?=e(($w['week_label']?$w['week_label'].' · ':'').$w['title'])?></option><?php endforeach?></select><a class="btn" href="<?=BASE_URL?>hoclieu_game_olympia.php">← Olympia chính</a></form></div><?php if($week):?><div class="card"><h2>Tạo bộ mới</h2><form method="post" class="row"><input type="hidden" name="csrf" value="<?=e($csrf)?>"><input type="hidden" name="action" value="create_set"><input type="hidden" name="week" value="<?=e($weekId)?>"><input name="title" placeholder="Tên bộ câu hỏi"><label><input type="checkbox" name="copy_official" value="1"> Sao chép câu hỏi bộ chính để chỉnh riêng</label><button class="btn">+ Tạo bộ</button></form><div class="muted">Tối đa 5 bộ đang hoạt động/tuần/tài khoản. Bộ lưu trữ không tính vào giới hạn.</div></div><div class="card"><h2>Bộ của tôi</h2><?php foreach($sets as $s):?><div class="set"><div><strong><?=e($s['title'])?></strong><div class="muted"><?=e($s['question_count'])?> câu · <?=e($s['status']==='ready'?'Đã hoàn thiện':'Nháp')?><?=$s['is_archived']?' · Đã lưu trữ':''?></div></div><a class="btn" href="?week=<?=e(rawurlencode($weekId))?>&set=<?=e(rawurlencode($s['id']))?>">Mở bộ</a></div><?php endforeach;if(!$sets):?><p class="muted">Chưa có bộ cá nhân.</p><?php endif?></div><?php if($set):?><div class="card"><h2><?=e($set['title'])?></h2><form method="post" class="row"><input type="hidden" name="csrf" value="<?=e($csrf)?>"><input type="hidden" name="action" value="save_set"><input type="hidden" name="week" value="<?=e($weekId)?>"><input type="hidden" name="set" value="<?=e($setId)?>"><input name="title" value="<?=e($set['title'])?>"><select name="status"><option value="draft" <?=$set['status']==='draft'?'selected':''?>>Nháp</option><option value="ready" <?=$set['status']==='ready'?'selected':''?>>Đã hoàn thiện</option></select><button class="btn">Lưu</button><a class="btn" href="<?=BASE_URL?>hoclieu_game_olympia_play.php?week=<?=e(rawurlencode($weekId))?>&set=<?=e(rawurlencode($setId))?>">Chơi thử bộ này</a></form></div><div class="card"><h2>Thêm câu hỏi</h2><form method="post"><input type="hidden" name="csrf" value="<?=e($csrf)?>"><input type="hidden" name="action" value="save_question"><input type="hidden" name="week" value="<?=e($weekId)?>"><input type="hidden" name="set" value="<?=e($setId)?>"><div class="row"><select name="stage_name"><?php foreach(['Khởi động','Vượt chướng ngại vật','Tăng tốc','Về đích'] as $st):?><option><?=e($st)?></option><?php endforeach?></select><label><input type="checkbox" name="all_grades" value="1" checked> Tất cả khối</label><input type="number" name="points" value="10" min="0" placeholder="Điểm"><input type="number" name="sort_order" value="0" min="0" placeholder="Thứ tự"></div><textarea name="question_text" required placeholder="Câu hỏi"></textarea><textarea name="answer_text" placeholder="Đáp án"></textarea><button class="btn">Lưu câu hỏi</button></form></div><div class="card"><h2>Nội dung (<?=count($questions)?>)</h2><?php foreach($questions as $q):?><div class="q"><strong><?=e($q['stage_name'])?> · <?=e($q['points'])?> điểm</strong><div><?=e($q['question_text'])?></div><div class="muted">Đáp án: <?=e($q['answer_text'])?> · Khối: <?=e($q['grade_scope'])?></div><form method="post" onsubmit="return confirm('Xóa câu hỏi này?')"><input type="hidden" name="csrf" value="<?=e($csrf)?>"><input type="hidden" name="action" value="delete_question"><input type="hidden" name="week" value="<?=e($weekId)?>"><input type="hidden" name="set" value="<?=e($setId)?>"><input type="hidden" name="question_id" value="<?=e($q['id'])?>"><button class="btn">Xóa</button></form><?php require __DIR__.'/includes/olympia_question_editor.php';?></div><?php endforeach?></div><div class="card row"><form method="post"><input type="hidden" name="csrf" value="<?=e($csrf)?>"><input type="hidden" name="action" value="archive_set"><input type="hidden" name="week" value="<?=e($weekId)?>"><input type="hidden" name="set" value="<?=e($setId)?>"><button class="btn">Lưu trữ bộ</button></form><form method="post" onsubmit="return confirm('Xóa bộ cá nhân và toàn bộ điểm chơi thử của bộ này? Bộ chính không bị ảnh hưởng.')"><input type="hidden" name="csrf" value="<?=e($csrf)?>"><input type="hidden" name="action" value="delete_set"><input type="hidden" name="week" value="<?=e($weekId)?>"><input type="hidden" name="set" value="<?=e($setId)?>"><button class="btn">Xóa bộ</button></form></div><?php endif?><?php endif?></main><?php require __DIR__ . '/includes/game_credit.php'; ?></body></html>
